<template>
<section v-if="modelValue&&preview" aria-label="完整物资序列声明编辑">
 <p>本次全部单位与日原件 {{modelValue.member_reviews.length}} 件；{{modelValue.days.length}} 个完整日、三个独立目标。分页只改变显示，保存始终包含全部声明。单位、原件标识与摘要来自本次完整捕获。</p>
 <label>本序列明确受审单位<select aria-label="本序列明确受审单位" :value="modelValue.unit_definition_id||''" @change="unit($event.target.value)"><option value="" disabled>明确选择原单位，不从目录推断</option><option v-for="u in units" :key="u.source_record_id" :value="u.source_record_id">{{u.payload.original_unit_text}} · {{u.source_record_id}}</option></select></label>
 <fieldset><legend>三个明确平滑参数（最简有理数，分母最多1000）</legend><div v-for="key in parameters" :key="key" class="parameter"><label>{{key}} 分子<input :aria-label="key+' 分子'" v-model="modelValue.parameters[key].numerator" inputmode="numeric"></label><label>{{key}} 分母<input :aria-label="key+' 分母'" v-model="modelValue.parameters[key].denominator" inputmode="numeric"></label></div></fieldset>
 <label>本次共用审阅依据（只复制文字，不决定任何用途或覆盖状态）<textarea aria-label="本次共用审阅依据" v-model="sharedBasis" rows="3"/></label><button type="button" :disabled="!supplySeriesBasis(sharedBasis)" @click="copyBasis">将本次依据复制到所有尚未填写的声明</button>
 <fieldset><legend>三个目标分别声明口径</legend><div v-for="r in modelValue.target_coverage" :key="r.target"><h4>{{labels[r.target]}}</h4><label v-for="key in coverageFields" :key="key">{{coverageLabels[key]}}<select :aria-label="r.target+' '+key" v-model="r[key]"><option value="" disabled>明确选择，不默认确认</option><option value="confirmed">明确确认</option><option value="not_confirmed">明确不确认</option><option value="unknown">原未知</option></select></label><textarea :aria-label="r.target+' 覆盖依据'" v-model="r.basis_note" rows="2"/></div></fieldset>
 <fieldset><legend>完整成员逐件用途</legend><p>已发布、当前可用的原件也须明确填写用途。多个同日同目标有效原件不能通过排除其一制造赢家。</p><table><thead><tr><th>类型、标识与原状态</th><th>本次用途</th><th>明确依据</th></tr></thead><tbody><tr v-for="r in memberPage" :key="r.source_kind+':'+r.source_record_id"><td>{{r.source_kind}} · {{r.source_record_id}}<br>{{source(r)?.status}}；{{source(r)?.eligible?'当前原件可用':'当前不能用于新序列'}}<br>{{originalText(r)}}</td><td><select :aria-label="r.source_record_id+' 原件用途'" v-model="r.selection"><option value="" disabled>明确用途</option><option value="confirmed" :disabled="!source(r)?.eligible">明确使用整件</option><option value="excluded">明确排除</option><option value="unknown">用途未知</option></select></td><td><textarea :aria-label="r.source_record_id+' 用途依据'" v-model="r.basis_note" rows="2"/></td></tr></tbody></table><nav aria-label="完整物资成员分页"><button type="button" :disabled="memberIndex===0" @click="memberIndex--">上一页成员</button><span>第 {{memberIndex+1}} / {{Math.max(1,Math.ceil(modelValue.member_reviews.length/20))}} 页</span><button type="button" :disabled="(memberIndex+1)*20>=modelValue.member_reviews.length" @click="memberIndex++">下一页成员</button></nav></fieldset>
 <fieldset><legend>全部日期、三个目标分别选择整件原件</legend><button type="button" @click="missing">将尚未选择的日期目标明确为缺失（不补零）</button><table><thead><tr><th>完整业务日与目标</th><th>整件原件或明确缺项</th><th>选择依据</th></tr></thead><tbody><template v-for="day in dayPage" :key="day.date"><tr v-for="r in day.selections" :key="r.target"><td>{{day.date}}<br>{{labels[r.target]}}</td><td><select :aria-label="day.date+' '+r.target+' 整件选择'" :value="choice(r)" @change="choose(r,$event.target.value)"><option value="" disabled>明确原件或缺项</option><option value="missing_selected_original">明确未选择原件</option><option value="unresolved_conflict">原件冲突未解决</option><option v-for="m in group(day.date,r.target)?.members||[]" :key="m.source_record_id" :value="m.source_record_id" :disabled="!selectable(day.date,r.target,m)">{{m.source_record_id}} · {{m.eligible?'当前已发布':'当前不可选'}}</option></select></td><td><textarea :aria-label="day.date+' '+r.target+' 选择依据'" v-model="r.basis_note" rows="2"/></td></tr></template></tbody></table><nav aria-label="完整物资日期分页"><button type="button" :disabled="dayIndex===0" @click="dayIndex--">上一页日期</button><span>第 {{dayIndex+1}} / {{Math.ceil(modelValue.days.length/7)}} 页</span><button type="button" :disabled="(dayIndex+1)*7>=modelValue.days.length" @click="dayIndex++">下一页日期</button></nav></fieldset>
</section>
</template>
<script setup>
import {computed,ref,watch} from 'vue';
import {supplySeriesBasis} from '@/api/ai/supplySeries';
const props=defineProps({modelValue:{type:Object,required:true},preview:{type:Object,required:true}});
const parameters=['alpha_size','alpha_interval','beta_occurrence'],coverageFields=['same_scope_confirmed','same_definition_confirmed','same_method_confirmed'],coverageLabels={same_scope_confirmed:'同一范围',same_definition_confirmed:'同一目标定义',same_method_confirmed:'同一计数方法'},labels={recorded_request_quantity:'已记录申请量',gross_fulfilled_issue_quantity:'实际毛发出量',confirmed_consumed_quantity:'已确认消耗量'},sharedBasis=ref(''),memberIndex=ref(0),dayIndex=ref(0);
const records=computed(()=>new Map([...props.preview.collection.unit_definitions,...props.preview.collection.source_records].map(r=>[r.source.source_kind+':'+r.source.source_record_id,r.source]))),units=computed(()=>props.preview.collection.unit_definitions.map(r=>r.source).filter(s=>s.eligible&&s.status==='published'&&s.professional_status==='confirmed')),memberPage=computed(()=>props.modelValue.member_reviews.slice(memberIndex.value*20,(memberIndex.value+1)*20)),dayPage=computed(()=>props.modelValue.days.slice(dayIndex.value*7,(dayIndex.value+1)*7));
function source(r){return records.value.get(r.source_kind+':'+r.source_record_id);}function originalText(r){const s=source(r);if(s?.payload===null)return'当前正文已隐去，仅保留原始摘要定位';return s?.source_kind==='unit_definition'?s.payload.original_unit_text:(s.payload.quantity.value??('原缺项：'+s.payload.quantity.absent_reason))+'；原单位：'+(s.payload.original_unit_text??'未知');}
function unit(id){const s=units.value.find(s=>s.source_record_id===id);if(!s)return;Object.assign(props.modelValue,{unit_definition_id:id,expected_unit_content_hash:s.content_hash,expected_unit_governance_hash:s.governance_hash});}
function copyBasis(){if(!supplySeriesBasis(sharedBasis.value))return;for(const r of [...props.modelValue.target_coverage,...props.modelValue.member_reviews,...props.modelValue.days.flatMap(d=>d.selections)])if(!r.basis_note)r.basis_note=sharedBasis.value;}
function group(date,target){return props.preview.groups.find(g=>g.date===date&&g.target===target);}function choice(r){return r.source_record_id??r.absent_reason??'';}function choose(r,value){if(['missing_selected_original','unresolved_conflict'].includes(value))Object.assign(r,{source_record_id:null,absent_reason:value});else Object.assign(r,{source_record_id:value,absent_reason:null});}
function selectable(date,target,m){const g=group(date,target);if(!m.eligible||m.status!=='published'||g.members.filter(r=>r.eligible&&r.status==='published').length>1)return false;const s=records.value.get('daily_quantity:'+m.source_record_id);return s?.payload?.date===date&&s.payload.timezone===props.preview.collection.request.timezone&&s.payload.day_start_at===g.day_start_at&&s.payload.day_end_at===g.day_end_at;}
function missing(){for(const d of props.modelValue.days)for(const r of d.selections)if(!choice(r))choose(r,'missing_selected_original');}
watch(()=>props.preview.collection.collection_digest,()=>{memberIndex.value=0;dayIndex.value=0;sharedBasis.value='';});
</script>
<style scoped>section{line-height:1.7}fieldset{margin:16px 0;border:1px solid #ddd;padding:12px}label{display:block;margin:8px 0}input,select,textarea{display:block;box-sizing:border-box;width:100%;padding:7px;border:1px solid #bbb;border-radius:4px;background:#fff;color:#222}table{width:100%;border-collapse:collapse;table-layout:fixed}td,th{border:1px solid #ddd;padding:8px;text-align:left;vertical-align:top;overflow-wrap:anywhere}nav{display:flex;gap:14px;margin-top:12px}.parameter{display:flex;gap:12px}.parameter label{flex:1}button{padding:7px 12px;cursor:pointer}button:disabled{cursor:default}</style>
